CREATE INDEX "django_admin_log_content_type_id_c4bce8eb" ON "django_admin_log" ("content_type_id");
CREATE INDEX "django_admin_log_user_id_c564eba6" ON "django_admin_log" ("user_id");
CREATE UNIQUE INDEX "course_course_prerequisites_from_course_id_to_course_id_149f0fd9_uniq" ON "course_course_prerequisites" ("from_course_id", "to_course_id");
CREATE INDEX "course_course_prerequisites_from_course_id_1eb9a439" ON "course_course_prerequisites" ("from_course_id");
CREATE INDEX "course_course_prerequisites_to_course_id_1aa39964" ON "course_course_prerequisites" ("to_course_id");
CREATE UNIQUE INDEX "course_course_sessions_course_id_classsession_id_594e9edc_uniq" ON "course_course_sessions" ("course_id", "classsession_id");
CREATE INDEX "course_course_sessions_course_id_84ff4446" ON "course_course_sessions" ("course_id");
CREATE INDEX "course_course_sessions_classsession_id_cdeb9408" ON "course_course_sessions" ("classsession_id");
CREATE INDEX "course_course_professor_id_75380238" ON "course_course" ("professor_id");
CREATE INDEX "django_session_expire_date_a5c62663" ON "django_session" ("expire_date");
CREATE INDEX "token_blacklist_outstandingtoken_user_id_83bc629a" ON "token_blacklist_outstandingtoken" ("user_id");
CREATE UNIQUE INDEX "enrollment_enrollment_student_id_course_id_d362dccb_uniq" ON "enrollment_enrollment" ("student_id", "course_id");
CREATE INDEX "enrollment_enrollment_course_id_addd967a" ON "enrollment_enrollment" ("course_id");
